mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float map(vec3 p) {
  return length(p) - (1.2 + 0.05 * sin(time * 3.0));
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -3.0);
  vec3 rd = normalize(vec3(p, 1.6));
  float t = 0.0;
  for (int i = 0; i < 40; i++) {
    float d = map(ro + rd * t);
    if (d < 0.002 || t > 6.0) break;
    t += d * 0.85;
  }
  vec3 col = vec3(0.01, 0.01, 0.02);
  if (t < 6.0) {
    vec3 pos = ro + rd * t;
    vec3 n = normalize(pos);
    float rim = pow(1.0 - max(dot(n, -rd), 0.0), 4.0);
    vec3 corona = 0.5 + 0.5 * sin(vec3(0.0, 1.5, 3.0) + atan(n.y, n.x) * 4.0 + time * 3.0);
    col = rim * corona * 3.5;
  }
  col = (col * (2.51 * col + 0.03)) / (col * (2.43 * col + 0.59) + 0.14);
  ret = col;
}
